WITH `t0` AS (SELECT `tenantId`, `entityId`, `version`, `market_stock_total` FROM `metric_group_ots_component_market_availability` FINAL WHERE `tenantId` = {p0:String}) SELECT `__typedhouse_input`.`__typedhouse_leaf_1` AS `entityId`, ifNull(`__typedhouse_input`.`__typedhouse_leaf_13`, {p1:Float64}) AS `stock` FROM (SELECT `c`.`entityId` AS `__typedhouse_leaf_1`, `a`.`market_stock_total` AS `__typedhouse_leaf_13` FROM (SELECT `entityId` FROM `entity_ots_component` WHERE `tenantId` = {p2:String}) AS `c` LEFT ALL JOIN (SELECT `m`.`entityId` AS `entityId`, `m`.`market_stock_total` AS `market_stock_total` FROM `t0` AS `m` INNER ALL JOIN (SELECT `tenantId`, `entityId`, max(`version`) AS `version` FROM `t0` GROUP BY `tenantId`, `entityId`) AS `v` ON `m`.`tenantId` = `v`.`tenantId` AND `m`.`entityId` = `v`.`entityId` AND `m`.`version` = `v`.`version`) AS `a` ON `c`.`entityId` = `a`.`entityId`) AS `__typedhouse_input` SETTINGS join_use_nulls = 1 /* join_use_nulls = 1: unmatched outer-join columns are NULL, not type defaults */
